-- =============================================================================
-- Migration 004 — Storage Buckets & Policies
-- Muski Birthday Site
--
-- Two private buckets:
--   media       → card photos, audio voice notes, short video clips
--   vault-media → vault item media (admin-only; E2E encrypted client-side)
--
-- Both buckets are PRIVATE (public = false).
-- Signed URLs are generated by the Supabase client library after the caller
-- is verified (either admin session or post-unlock anon — RLS enforces both).
-- =============================================================================

-- =============================================================================
-- Bucket: media
-- Used for card photos, audio clips, and video attached to scratch cards.
-- =============================================================================
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'media',
  'media',
  FALSE,    -- private — no public URL access; signed URLs only
  5242880,  -- 5 MB per file (cards compress photos to ~200 KB WebP client-side)
  ARRAY[
    'image/webp',
    'image/jpeg',
    'image/png',
    'audio/webm',
    'audio/ogg',
    'audio/mpeg',
    'video/webm',
    'video/mp4'
  ]
)
ON CONFLICT (id) DO NOTHING;

-- =============================================================================
-- Bucket: vault-media
-- Stores E2E encrypted vault item media (photos, audio).
-- Only admin can access; content is opaque ciphertext.
-- =============================================================================
INSERT INTO storage.buckets (id, name, public, file_size_limit)
VALUES (
  'vault-media',
  'vault-media',
  FALSE,    -- private
  5242880   -- 5 MB per file
)
ON CONFLICT (id) DO NOTHING;

-- =============================================================================
-- Storage RLS policies
-- storage.objects rows represent files. The bucket_id column links to the
-- bucket. Policies here gate signed-URL generation (SELECT) and uploads
-- (INSERT/DELETE).
-- =============================================================================

-- ── media bucket ─────────────────────────────────────────────────────────────

-- Admin can upload to the media bucket (direct admin uploads: face photos, etc.)
-- Contributor uploads are handled by an Edge Function or client-side flow
-- that uses the service role key after validating the contributor token.
-- This policy covers the admin's own uploads.
CREATE POLICY "media_insert_admin"
  ON storage.objects
  FOR INSERT
  WITH CHECK (
    bucket_id = 'media'
    AND is_admin()
  );

-- Signed URL creation (which requires SELECT on the object row):
-- Admin: always allowed (preview before unlock).
-- Anon/authenticated non-admin: only after unlock.
CREATE POLICY "media_select_unlocked_or_admin"
  ON storage.objects
  FOR SELECT
  USING (
    bucket_id = 'media'
    AND (is_admin() OR is_unlocked())
  );

-- Admin can delete files (e.g. after rejecting a card with media)
CREATE POLICY "media_delete_admin"
  ON storage.objects
  FOR DELETE
  USING (
    bucket_id = 'media'
    AND is_admin()
  );

-- ── vault-media bucket ────────────────────────────────────────────────────────

-- All vault-media operations restricted to admin only.
-- Even though content is encrypted, we keep it admin-only to avoid
-- leaking metadata (file sizes, counts) to anonymous users.
CREATE POLICY "vault_media_admin_all"
  ON storage.objects
  FOR ALL
  USING (
    bucket_id = 'vault-media'
    AND is_admin()
  );
